# How one entity is loaded from what the system recorded. This is the one artefact whose job
# is to bind two vocabularies, so it names both -- but only in table, primary_keys and
# transformation_expression. See docs/conventions.md section 1.4.
entity_id: ORDER
mapping_groups:
  - name: default_mapping_group
    tables:
      - connection: dev
        table: das__staged.orders
        primary_keys: [order_id]
        ingestion_strategy: FULL_LOG
        entity_effective_timestamp_expression: extracted_at
        attributes:
          - {id: ORDER_NUMBER, transformation_expression: cast(order_id AS VARCHAR)}
          - {id: PLACED_ON, transformation_expression: order_date}
          - {id: DESTINATION_COUNTRY, transformation_expression: ship_country}
          - {id: FREIGHT_CHARGE, transformation_expression: freight}
    # M6. The id is <SRC>_<NAME>_<TGT>; source_table is byte-identical to the table above,
    # because a mismatch is skipped in silence; and the target expression is spelled exactly
    # as customer-mapping.yaml spells its own key, because a different spelling produces
    # pairs that join to nothing and nothing says so at deploy, at execute or in either
    # acceptance query.
    relationships:
      - id: ORDER_IS_PLACED_BY_CUSTOMER
        source_table: das__staged.orders
        target_transformation_expression: customer_id
=== json ===
              "id": "FREIGHT_CHARGE",
              "transformation_expression": "freight"
            },
            {
              "id": "ORDER_DESTINATION_COUNTRY_EFF_TMSTP",
              "transformation_expression": "extracted_at"
            },
            {
              "id": "ORDER_FREIGHT_CHARGE_EFF_TMSTP",
              "transformation_expression": "extracted_at"
            }
          ]
        }
      ],
      "relationships": [
        {
          "atomic_context": "ORDER_IS_PLACED_BY_CUSTOMER",
          "source_table": "das__staged.orders",
          "target_transformation_expression": "customer_id"
        }
      ]
    }
  ],
  "template_model_source": "",
  "template_generated_at": ""
}

